    "foldDesignNote": "巻いた形（完成形）の断面を先に作ります。ボタンが3枚を通る縦線（ボタン線）から、左右の折りの外側までの距離・左右の革の切り口までの距離・左右の折りの内側の半径を入れて押してください。表・裏の革の厚みは、下の「表（外側の革）の厚み」「裏（内側の革）の厚み」に入れます（空欄なら「革1枚の厚み」を使い、2枚貼り合わせ）。最左端から最右端までの距離（全幅）は、左右の距離の合計です。全幅の欄に入れると、左の距離はそのままで右の距離が合います。ボタンの位置は、ずらす量を入れて「ボタンを左へ／右へ」で動かせます（4つの距離の欄が書き換わり、全幅は変わりません）。折りが重なる・3枚目が折りを突き抜ける寸法は、作ったうえで警告を出します。",
