    "ctxRpatchTip": "外形（閉じた図形）の中をクリックすると、外形をランダムに切るカット線（青）を作り、カット線の両側に縫い線（点線）と縫い穴（丸目のピッチ）を作ります。交点の4つの穴は正方形（斜めはひし形）になり、交点から離れた所は、カット線の両側の穴が向かい合い、間隔が縫い線の間隔（距離×2＝既定 4mm）ぴったりの正方形に並びます（交点から最初の穴までの間だけ、余りを持ちます）。外周の菱目の近くは、外周の菱目に統合します。「今ある青線を使う」にすると、いまある青い直線に縫い穴を付けます。",
