    "divideBarTip": "角：2本の線が交わる所の近くを、線から離れた角の中でクリックすると、いちばん近い交点から、クリックした側の角を等分する線を引きます（分割数 2 は二等分線、3 は三等分線。長さを空にすると、交点から2本の線の端までのうち短い方）。線：1本の線の上をクリックすると、その線を等分する点（2＝中点）から、クリックした側へ垂直な線を引きます（長さを空にすると線の半分・最大 30mm。折れ線はクリックした辺、円弧は弧の長さを等分）。目印の位置を入れると、引いた線の上の、交点・分割点から入れた距離の所に点の目印も打ちます。",
    "hint.divide": "角を等分：2本の線が交わる所の近くを、等分したい側の角の中でクリック。線を等分：1本の線の上をクリックすると、等分する点（2＝中点）から、クリックした側へ垂直な線を引きます（上の窓で、分割数・長さ・目印の位置を決められます）。",
    "divideNoCross": "近くに、交わる2本の線がありません。角を等分するなら交点の近くを角の中で、線を等分するならその線の上をクリックしてください。本体の中心線なら、向かい合う2辺のあいだ（本体の中）をクリックしてください。",
