    "modHelp.stitch": "クリック：始点→終点の順に2回クリックして、その間に打つ（端・交点・穴に吸着）\n固定ピッチ：始点から終点を超えない所まで／可変ピッチ：両端に合わせて均等／個数指定：両端を含めてN個\nAlt＋クリック：1穴だけ打つ",
    "modHelp.trim": "クリック：クリックした部分（交点で区切った区間）を消す\nShift＋クリック：クリックした側を残す\nAlt＋クリック：菱目と菱目の間の線だけを切る",
    "modHelp.offset": "クリック：他の図形との交点から交点までを選ぶ\nダブルクリック：つながった図形全体を選ぶ（Enter で実行）\nAlt＋クリック：矩形などの1辺だけ",
