    "ctxHolesBack": "外れた穴を、線の上へ戻す（橙の輪の穴）",
    "ctxHolesBackTip": "橙の輪と点線が付いた穴（持ち主の線から外れた穴）を、点線の先＝線の上のその穴の位置へ戻します。選んだ穴・選んだ図形の範囲の穴だけ（何も選んでいなければ図面全体）。向きは変えません。ただし、線の上の同じ位置に重なっている穴（元の位置が分からない穴）は動かしません。元に戻すは1回です。",
    "ctxLinesToHoles": "点線を、穴の位置へ寄せる（橙の輪の穴）",
    "ctxUnlinkLines": "見えない補助の線を、点線に戻す（複製した部品）",
    "ctxUnlinkLinesTip": "選んだ部品の枠の中にある「見えない補助の線」（点線を隠したまま複製したときに、縫い線が変わったもの）を、ふつうの点線に戻します。ピッチのずれの印が出るようになり、点線の表示を入れると線も見えます。取り込み（.lcc）の補助の線は戻しません。元に戻すは1回です。",
    "unlinkNone": "戻せる見えない補助の線がありません。複製した部品（外形）を選んでから押してください。",
    "unlinkDone": "見えない補助の線 {n} 本を、点線に戻しました（菱目 {m} 個）。ピッチのずれの印が出ます。",
    "ctxLinesToHolesTip": "橙の輪と点線が付いた穴（持ち主の点線から離れた穴）の持ち主の点線を、穴のずれのぶん動かして、穴の位置へ寄せます。部品を動かして、点線だけが置いていかれたときに使います。穴は動かしません。対象は、点線（ガイド層・点線の線）が持ち主で、穴の半分以上が同じずれにそろっている経路だけ。選んだ穴・選んだ図形の範囲だけ（何も選んでいなければ図面全体）。元に戻すは1回です。",
    "linesToHolesDone": "点線 {k} 本を、穴の位置へ寄せました。橙の輪の穴 {n} 個のうち {fit} 個が、線の上に乗ります。残りは、右クリックの「外れた穴を、線の上へ戻す」で合わせられます。元に戻すは1回です。",
    "linesToHolesNone": "寄せる点線がありません（橙の輪の穴 {k} 個）。対象は、持ち主が点線（ガイド層・点線の線）だけで、穴の半分以上が同じずれにそろっている経路です。",
