    "patchStitchTip": "入れる：ひし形の大きさは、縫い穴の間隔（基準ピッチ）に合わせて少し調整され、縫い合わせと縫い穴（外周の穴も）が付きます。切（初めの状態）：縫い合わせ・縫い穴・外周の穴は付けず、ひし形の大きさは、入れた目標（幅・高さ）どおりになります。大きさを決めるときは外して作り、決まってから入れて作りなおせば、縫い穴を付けられます。",
