    "patchPreferNearTip": "ひし形の大きさは、縫い穴の間隔にそろえるため、段階になります。入れると、目標にいちばん近い段階を使います。切ると、縫い穴が全部付く段階を優先します（目標から少し離れることがあります）。",
    "patchKeepSize": "調整しない：ひし形の大きさは入れたまま・すでにある外周の菱目も動かさない",
    "patchKeepSizeTip": "入れると、ひし形の大きさは入れた目標（列・行・幅・高さ）どおりのままになります。ベースに菱目を打ってあって、その上にパッチワークの模様だけを置きたいときに使います。縫い穴は同じ間隔で付きますが、向かい合う穴の位置はそろいません。また、すでにある外周の菱目（ベースに均等に打ったもの）は、パッチの境目にかかっていても、動かしません（かかっているかどうかは、案内の「外周の穴の点検」に出ます）。切ると、これまでどおり、穴の間隔に合わせて少し調整され、境目にかかった外周の菱目は、線に沿ってずれます。",
    "patchMinPiece": "端切れを省く大きさ（マス1つの面積の％）",
