    "helpSearch": "ヘルプを検索",
    "helpAll": "すべてのページ",
    "helpNoMatch": "見つかりません。",
    "tourTitle": "はじめに（5 枚）",
    "tourSkipAlways": "次からは表示しない",
    "tourSkip": "スキップ",
    "tourNext": "次へ",
    "tourFinish": "始める",
    "tour.1": "ようこそ。これはレザークラフトの型紙を作る、ブラウザだけで動く CAD です。N's factory の製品づくりに特化しており、一般的な製図には向きません。単位は mm、黒い画面に金色の線で描きます。",
    "tour.2": "左のツールで作図します。直線・矩形・円・円弧・ベジェ・ペン・文字・寸法のほか、丸め・面取り・オフセット・トリム・線対称もあります。下の入力欄に「100<0」のように打っても描けます。置いた文字は、ダブルクリックすると、フォントと大きさを変えられます。",
    "tour.3": "目打ちは、画面を右クリック（または上の「機能」ボタン）して、「目打ち・縫い穴」の「目打ち」から始めます（Shift+S でも始められます）。線の上で始点→終点の順に2回クリックすると、縫い穴が並びます。工具やピッチは「目打ちの設定・穴の編集」で選べます。",
    "tour.4": "機能は、右クリックか上の「機能」ボタンの一覧にまとまっています：選んだ図形、レイヤー、目打ち・縫い穴、パッチワーク、シミュレーション（色・2つ折り・3つ折り）、部品・金具ライブラリ、作図オプション・寸法、出力・下絵・その他（レシピ・AI 相談など）。選ぶと、その設定が右の列に出ます（右上の「▤ パネル」でも一覧が開きます）。3D は上の「3D」ボタンです。パッチワーク・2つ折り・3つ折りは、将来の有料版の機能で、ロックされています。",
    "tour.5": "出力は、「出力・下絵・その他」の「出力」から。上の「保存」からも、SVG・PDF・DXF・PNG を書き出せます。印刷は校正スケールで 100mm を確かめてから。印刷・保存・書き出しは、利用登録（メールアドレス）が必要です（描く・見る・自動保存は登録なしで使えます）。困ったら「？」キーでヘルプ、ツールボタンの右クリックでそのツールの説明が開きます。",
    "helpPlay": "やってみせる",
    "tutPlay": "再生",
    "tutPause": "一時停止",
    "tutResume": "続ける",
    "tutStop": "終了",
