    "splitLines": "Split at intersections",
    "outDedupe": "Merge overlapping lines on export (for laser)",
    "outDedupeTip": "When exporting SVG, PDF or DXF, overlapping lines (edges shared by neighboring cells, doubled lines, the same curve with slightly shifted vertices, the same arc) are exported once, so the laser does not travel the same place again and again. The drawing data is not changed. For overlaps of different colors the colored line is kept. Lines with a stitch-hole route and painted shapes are exported as they are.",
    "outDedupeNote": "Removed {mm} mm of overlapping lines on export ({n} shapes tidied).",
    "outBeamFix": "Screen-matching correction (Beam Studio; not needed for the real cut)",
    "outBeamFixTip": "In Beam Studio's screen, each color layer is sized about one stroke width (about 0.35 mm) too large and drawn shrunk, so thin layers (only dotted lines or stitch holes) look a few percent smaller and drift from the cut line. This is only how the screen draws them: the numbers sent to the machine and the real cut stay exactly as in N's CAD (confirmed on a real cut: a 143 mm line was cut at 143 mm). When on, only the thin layers are enlarged by the amount they look shrunk, so they line up on screen, but on the real cut they end up about 1 to 2.5 mm too far out at the ends. Turn it on only to line things up on screen. It is off by default (your choice is remembered).",
    "outBeamFixNote": "Corrected {n} layer(s) for Beam Studio.",
    "presenceSuffix": " online",
    "presenceTip": "People with N's CAD open right now (updated about every 30 seconds, including you). To count them, only a random anonymous string, made anew each time you open the page, is sent (no name, drawing or file name).",
    "selOutline": "Select outline only",
    "selDedupe": "Merge overlapping lines",
