    "divideHowTwo": "Pick two points (mark the middle)",
    "divideHowTip": "\"Click a line\": draws a perpendicular dashed line from the point that divides the clicked line equally (at a crossing, it divides the angle). \"Pick two points\": click the start, then the end, and a short mark line perpendicular to the line joining them is drawn at the middle (or at each dividing point when the number of parts is 3 or more).",
