    "divideTwoFirst": "Click the start point. Then click the end point to draw the mark at the middle (or at each dividing point when the number of parts is 3 or more). Shift = horizontal/vertical, Esc = cancel.",
    "divideTwoSecond": "Click the end point (Shift = horizontal/vertical, Esc = cancel).",
    "divideTwoSame": "The start and end points are the same. Click a point further away.",
    "divideTwoDone": "Drew mark lines (length {len} mm) at {n} point(s) dividing start to end into {parts} parts. Undo takes one step. The mark type, length and color become the starting values next time.",
    "divideLineFirst": "Click a line to draw a perpendicular line from the point that divides it equally. Click near a crossing to divide the angle.",
    "ctxRpatch": "Random patchwork (cut the outline at random and punch the stitch holes)",
    "ctxRpatchTip": "Click inside an outline (a closed shape) to make blue cut lines that divide it at random, then stitch lines (dashed) 2 mm on each side of every cut line, with stitch holes at the awl pitch. The four holes at a junction form a square (a rhombus when the lines are not square to each other), and away from junctions the holes on both sides face each other at exactly the distance between the two stitch lines (distance × 2 = 4 mm by default), so every four neighbouring holes form a square (only the gap from a junction to its first hole takes up the remainder). Holes near the outer stitch row merge into it. With \"Use existing blue lines\", the stitch holes are added to the blue straight lines that are already there.",
    "hint.rpatch": "Random patchwork: click inside an outline (a closed shape) to make the cut lines and the stitch holes. \"Another plan\" changes the seed and redoes it.",
    "rpBarTip": "Choose how to make it, then click inside the outline. Cut at random: the number of lines, the minimum piece width and the random seed decide the shape (same settings, same result). Use existing blue lines: only the stitch holes are added to the blue straight lines that are already there. The stitch line distance (from the blue line), the pitch tolerance and the distance of the outer stitch row from the edge decide how the holes are placed.",
    "rpHow": "Method",
    "rpHowRandom": "Cut at random",
    "rpHowExisting": "Use existing blue lines",
    "rpCount": "Number of lines",
    "rpMin": "Minimum piece width (mm)",
    "rpSeed": "Random seed",
    "rpNext": "Another plan",
    "rpNextTip": "Advances the random seed by one and redoes the same outline with different cut lines (the previous one is replaced).",
