    "rpTryTip": "Makes that many different cuts and picks the one whose pieces vary least in area among those with the most lines. 1 = no evening out (pure random). More candidates give more even areas.",
    "rpAreaInfo": "Piece areas: min {min} to max {max} cm² (variation {cv}%, best of {n} candidates).",
