    "rpPlanTitle": "Plan {n}",
    "rpAreaShort": "Area {min} to {max} cm² · variation {cv}%",
    "rpShapeInfo": "Piece shapes: {tri} triangles, {quad} quadrilaterals, {other} pentagons or more.",
    "ctxRcolor": "Random coloring (paint the pieces so similar colors never touch)",
    "ctxRcolorTip": "Click inside an outline (a closed shape) to paint the pieces enclosed by the outline and the cut lines (blue straight lines) with colors chosen from the ones you check. The color distance (ΔE) between neighboring pieces is kept at or above the threshold, and the colors are used about equally. The result stays as the color fills of the color simulation.",
    "hint.rcolor": "Random coloring: click inside an outline (a closed shape) to paint the pieces. \"Another plan\" and \"Compare plans\" let you choose other colorings.",
    "rcBarTip": "Check the colors to use, then click inside the outline. Neighboring colors are chosen so that their distance (ΔE) is at or above the threshold (larger = clearly different colors). If there are too few colors to keep it, the number of too-close neighbors is reported.",
    "rcPalette": "Colors",
    "rcDE": "Min ΔE of neighbors",
    "rcTry": "Candidates",
    "rcTryTip": "Makes that many different colorings and picks the best. More candidates find better plans.",
    "rcSeed": "Random seed",
    "rcNext": "Another plan",
    "rcNextTip": "Advances the random seed by one and repaints the same pieces with a different coloring (the previous one is replaced).",
    "rcCompare": "Compare plans",
    "rcCompareTip": "Lines up the best 4 colorings of the same pieces as small colored drawings with numbers. The one you pick is applied to the drawing.",
    "rcFewColors": "Check at least two colors to use.",
    "rcNoPieces": "No pieces found. Check that the outline (a closed shape) and the blue straight lines (cut lines) inside it are connected.",
    "rcDone": "Painted {n} pieces with colors chosen from {k}.",
    "rcDoneOk": "All neighboring colors are at ΔE {de} or more (smallest {d}).",
    "rcDoneBad": "{bad} neighboring pairs are below ΔE {de} (smallest {d}). Use more colors or lower the threshold.",
    "rcPlanStat": "Smallest neighbor distance {d} · too-close pairs {bad}",
    "rcResultTitle": "Pieces and area per color (leather needed)",
    "rcResultN": "{n} pcs",
    "rcResultA": "{a} cm²",
    "rcResultTotal": "Total {n} pcs · {a} cm²",
    "ctxRsplit": "Save pieces separately (SVG for laser cutting)",
    "ctxRsplitTip": "Click inside an outline (a closed shape) to split it exactly along the cut lines (blue straight lines), make one SVG per piece and save them together in one ZIP. Cut lines are black, stitch holes red and the number blue, so the laser can assign a process to each color. If the pieces are colored, the color name is added to the file name.",
    "hint.rsplit": "Save pieces separately: click inside an outline (a closed shape) to save one SVG per piece in a ZIP.",
    "rsBarTip": "Choose whether to engrave numbers and include stitch holes, then click inside the outline. The number is engraved as stroke characters at the point of the piece farthest from the edge (pieces that are too small get none).",
    "rsNum": "Engrave numbers",
    "rsHoles": "Include stitch holes",
    "rsNumH": "Number height (mm, max)",
    "rsMargin": "Margin (mm)",
    "rsPieceTitle": "Piece {n}",
    "rsDone": "Saved {n} pieces as one SVG each in a ZIP (leather-pieces.zip), with {holes} stitch holes.",
    "rsSkipped": "{n} pieces were too small to take a number.",
    "rsUnused": "{n} lines did not split any piece (for example lines that do not reach the outline).",
    "rpRebuild": "Rebuild holes",
    "rpRebuildTip": "After moving the blue lines (cut lines), press this to rebuild the stitch lines, stitch holes, red circles and the outer row to match the blue lines as they are now (the blue lines themselves are not moved). It works with both the randomly cut blue lines and the ones you drew.",
    "rpRecolorNote": "The color fills (random coloring) are left as they are because the piece shapes changed. Run \"Random coloring\" again.",
    "rpDoneRandom": "Cut the outline at random with {made} lines (requested {req}, seed {seed}).",
    "rpDoneExisting": "Added stitch holes to the {n} existing blue lines.",
    "rpDoneCommon": "{cross} junctions, {holes} stitch holes, {rim} outer-row holes ({merged} merged into existing holes).",
    "rpDoneOk": "The pitch is within the tolerance (±{tol}%) in every interval.",
    "rpDoneBad": "{n} interval(s) are outside the pitch tolerance (±{tol}%) (red circle, and the amount in mm to lengthen (+) or shorten (−) that interval so it divides exactly). Moving a blue line fixes it.",
    "rpFewer": "Keeping the minimum width of {min} mm, only {made} lines could be cut (requested {req}).",
    "divideBarN": "Divisions (2 = bisect; an angle or a line)",
    "divideBarLen": "Line length (mm, empty = auto)",
    "divideBarMark": "Mark position (mm from the intersection / division point, empty = none)",
    "divideBarTip": "Angle: click near where two lines cross, inside the angle (away from the lines). From the nearest intersection, lines are drawn that divide the angle on the side you clicked into equal parts (2 = bisector, 3 = trisectors; with the length empty, the shorter of the two arms is used). Line: click on a single line to draw perpendiculars from the points that divide it into equal parts (2 = midpoint), toward the side you clicked (length empty = half the line, at most 30 mm; a polyline uses the edge you clicked, an arc divides its arc length). If you enter a mark position, a dot mark is also placed on each drawn line at that distance from the intersection or division point.",
    "hint.divide": "Divide an angle: click near where two lines cross, inside the angle. Divide a line: click on a single line to draw perpendiculars from its division points (2 = midpoint) toward the side you clicked (set divisions, length and mark position in the box above).",
    "divideNoCross": "No two crossing lines nearby. To divide an angle, click near an intersection inside the angle; to divide a line, click on that line. For a centre line, click between two facing edges (inside the body).",
    "divideDone": "At the intersection ({x}, {y}), drew {k} line(s) dividing the {a}° angle into {n} equal parts ({each}° each, length {len} mm). Undo reverts it in one step.",
    "divideLineDone": "From the points dividing the line (length {L} mm) into {n} equal parts, drew {k} perpendicular line(s) toward the side you clicked ({each} mm apart, length {len} mm). Undo reverts it in one step.",
    "divideMarkNote": "Placed {m} mark(s), {d} mm from the intersection.",
    "divideMidDone": "Between two parallel lines ({gap} mm apart), drew {k} line(s) dividing the gap into {n} equal parts (2 = the centre line, length {len} mm). Undo reverts it in one step.",
    "divideMarkOut": "The mark position is farther than the line length, so no mark was placed (line length {len} mm).",
    "hint.mark": "Click on a line or curve to drop a dot mark at that spot, one at a time. Connected lines are treated as one path, passing through their joints. Dot size is \"Dot diameter\" in the Stitching card.",
