    "foldDesignErr_flatShortBi": "With these sizes the flat part (cover) gets a negative length. Make the closed width larger, or the spine inner radius or leather thickness smaller.",
    "foldFixNoneBi": "Make the section first (step 1, \"Make the section\"). Enter the width and other numbers in \"Detailed settings\" just below it.",
