    "ctxLibOpen": "Open the parts library",
    "ctxSimStitch": "Stitch (show stitches)",
    "stitchSimOn": "Stitch simulation is on: thread stitches are drawn between the holes (screen only; in PNG export only when “Include stitches (PNG)” is ticked). Thread thickness and the stitch side (front/back) are in the View menu; thread color is set per path.",
