    "libOrganize": "Organize (headings, order)",
    "libOrganizeTip": "Create, rename and reorder headings; move parts to another heading and put your most-used parts first. The arrangement is saved in this browser.",
    "libOrgTitle": "Organize the parts library",
    "libOrgLead": "Rename a heading right in its box. Use the arrows to change the order, and the menu beside a part to move it to another heading. Put your most-used parts at the top.",
