    "layerGrpShow": "Show",
    "layerGrpPick": "Select",
    "layerGrpMove": "Move",
    "layerGrpLayer": "Layer",
    "layerSoloTip": "Show only the drawing layer (●) and hide the others.",
    "layerAllTip": "Show every layer.",
    "layerPickYellowTip": "Select every yellow dashed shape (offset lines etc.).",
    "layerPickDashedTip": "Select every dashed shape regardless of color (to move them to the guide layer at once).",
    "layerMoveTip": "Move the selected shapes to the drawing layer (●). For another layer, use \"Move here\" on that layer's row.",
    "removeLayerTip": "Remove the drawing layer (a layer with shapes, or the last layer, cannot be removed).",
    "layerIntro": "A layer is a \"transparent sheet\" that holds some of your shapes. For each sheet you can:\n1. Show or hide it, or lock it (so it cannot be moved by accident)\n2. Change what covers what (the higher in the list, the closer to the front)\n3. Move the selected shapes to another sheet\nNew shapes go onto the sheet chosen as the Drawing layer.",
    "ctxLayersTitle": "Move: the selected shapes to this layer (upper layers are in front)",
    "ctxLayerTip": "Press to move the selected shapes to this layer (undo reverts it in one step).",
    "ctxLayerBlockedTip": "This layer is locked, so shapes cannot be moved there (unlock it in the Layers card).",
    "ctxLayerHiddenTip": "This layer is hidden. Moved shapes will no longer be visible (turn on Show in the Layers card to see them).",
    "ctxLayerNew": "+ Create \"{name}\" and move there",
    "ctxLayerNewTip": "Creates a new numbered layer with the same name as the selection's layer, right in front of it, and moves the selected shapes there. Use it to change what covers what even within the same pattern.",
    "addLayerTip": "Creates a new numbered layer with the same name as the drawing layer, right in front of it (Pattern -> Pattern 2 -> Pattern 3). Reorder with the up/down arrows.",
    "layerCtxTip": "Manage the \"transparent sheets\" that hold your shapes: show, hide or lock each sheet, reorder what covers what, and move the selected shapes to another sheet.",
    "layerCtxOpened": "Layers opened. They are \"transparent sheets\" for your shapes: show, hide or lock / reorder what covers what (up arrow = front, down arrow = back) / move the selected shapes to another sheet.",
    "layerUpTip": "Bring forward (swap with the layer above)",
    "layerDownTip": "Send back (swap with the layer below)",
    "layerOrderMoved": "Moved layer \"{name}\": {dir}. What covers what is decided by the layer order (top = in front).",
    "layerMovedFront": "brought forward",
    "layerMovedBack": "sent back",
    "locked": "Locked",
    "addLayer": "Add",
    "showSolid": "Show solid lines",
    "showModHelp": "Operation tips",
    "showModHelpTip": "Show or hide the list of click / double-click / Shift / Alt operations at the top left of the canvas when you pick a tool. Turn it off once you are used to it.",
    "showSolidTip": "Show or hide solid lines (screen only; printing and export always include them; separate from layers). Hidden lines cannot be clicked and do not snap.",
    "showDashed": "Show dashed lines",
    "showZipper": "Show zipper drawings",
    "showZipperTip": "When off, lines made into zippers are shown as plain lines on screen (so you can see the lines and dimensions under the drawing). Print and export follow \"Include zipper drawings\" in the output card. Tape-width warnings still appear.",
    "showZipperOn": "Zipper drawings are shown.",
