    "patchStitchTip": "On: the diamond size is adjusted a little to the stitch spacing (base pitch), and seams and stitch holes (rim holes too) are added. Off: no seams, stitch holes or rim holes are added, and the diamond size is exactly your target (width/height). Decide the size with it off, then turn it on and rebuild to add the holes.",
    "patchEdgeBan": "No diamond holes within 2.5 mm of an edge (uncheck to allow)",
    "patchPreferNear": "Prefer the size closest to the target (some thin pieces may get no stitch holes)",
    "patchPreferNearTip": "The diamond size is stepped so that it fits the stitch-hole spacing. When checked, the step closest to the target is used. When unchecked, the step where every piece gets stitch holes is preferred (it can be a little off the target).",
    "patchKeepSize": "Do not adjust: keep the diamond size I entered and do not move the existing rim holes",
    "patchKeepSizeTip": "When ticked, the diamonds keep exactly the size you entered (columns, rows, width, height). Use it when the base already has stitch holes and you only want to lay the patchwork pattern on top. Stitch holes keep the same spacing, but facing holes will not line up. Existing rim holes (punched evenly on the base) are not moved even if they fall on a patch boundary (the rim check in the notice tells you). When unticked, the size is adjusted slightly to the hole spacing as before, and rim holes on a boundary slide along the line.",
    "patchMinPiece": "Drop scraps smaller than (% of one cell's area)",
    "patchMinPieceTip": "Thin pieces cut off at the edge of the frame are dropped when they are smaller than this percentage of one cell (default 5). If the piece count jumps when you change the size slightly, raise or lower this number to find the value that keeps the thin pieces you want. 0 keeps every scrap, however thin (0 to 50).",
