let language = 'ja';
export function setLang(lang) { language = lang === 'en' ? 'en' : 'ja'; return language; }
export function t(key, vars = {}) { return (MESSAGES[language][key] ?? key).replace(/\{(\w+)\}/g, (_, name) => String(vars[name] ?? '')); }
